// Glossary content lives here (not in the i18n dictionary) because it's bulky,
// multilingual prose. Only the modal's chrome strings go through i18n.
/** Pick the text for the active language. Accepts a term or a category. */
function pick(entry, lang) {
    return lang === "pt-BR" ? entry.ptBR : entry[lang];
}
function pickTerm(entry, lang) {
    if (lang === "it")
        return entry.termIt;
    if (lang === "de")
        return entry.termDe;
    if (lang === "pt-BR")
        return entry.termPtBR;
    if (lang === "fr")
        return entry.termFr;
    return entry.term;
}
