const GAME_POLL_MS = 2000;
const GAME_REPORT_TIMEOUT_MS = 30000;
const MAX_PENDING_GAME_REPORTS = 2;
const isSameOwnershipReport = (a, b) => (isSameGameReport(a, b) && a.steamProfile === b.steamProfile);
function startGameWatcher() {
    let alive = true;
    let unregister = null;
    let pollTimer = null;
    let committed;
    let desired = { appid: null, name: null, steamProfile: "unknown" };
    let inFlight;
    let nextRequestId = 0;
    const pendingRequestIds = new Set();
    const clearActiveRequest = (request) => {
        if (inFlight?.id !== request.id)
            return false;
        if (request.timeout !== null)
            clearTimeout(request.timeout);
        inFlight = undefined;
        return true;
    };
    const sendDesired = () => {
        if (!alive
            || inFlight
            || pendingRequestIds.size >= MAX_PENDING_GAME_REPORTS
            || (committed && isSameOwnershipReport(desired, committed)))
            return;
        const request = {
            id: ++nextRequestId,
            target: desired,
            timeout: null,
        };
        inFlight = request;
        pendingRequestIds.add(request.id);
        request.timeout = setTimeout(() => {
            if (!alive || !clearActiveRequest(request))
                return;
            sendDesired();
        }, GAME_REPORT_TIMEOUT_MS);
        try {
            Promise.resolve(setCurrentGame(request.target.appid, request.target.name, request.target.steamProfile))
                .then(() => {
                pendingRequestIds.delete(request.id);
                if (!alive)
                    return;
                clearActiveRequest(request);
                committed = request.target;
                sendDesired();
            })
                .catch(() => {
                pendingRequestIds.delete(request.id);
                if (!alive)
                    return;
                clearActiveRequest(request);
            });
        }
        catch {
            pendingRequestIds.delete(request.id);
            clearActiveRequest(request);
        }
    };
    const report = (confirmIdle = false) => {
        if (!alive)
            return;
        const next = readRunningGame();
        const profile = readSteamPerformanceProfile(next?.liveAppid ?? null);
        desired = {
            appid: next ? next.appid : null,
            name: next ? next.name : null,
            steamProfile: profile === "game" ? "active" : profile === "global" ? "inactive" : "unknown",
        };
        if (desired.appid === null && committed === undefined && !inFlight && !confirmIdle)
            return;
        sendDesired();
    };
    const unsubscribePerformance = subscribeSteamPerformanceState(() => report());
    report();
    pollTimer = setInterval(() => report(true), GAME_POLL_MS);
    try {
        const reg = SteamClient?.GameSessions?.RegisterForAppLifetimeNotifications?.(() => report());
        if (reg && typeof reg.unregister === "function") {
            unregister = () => {
                try {
                    reg.unregister();
                }
                catch {
                    /* ignore */
                }
            };
        }
    }
    catch { /* polling remains active */ }
    return () => {
        alive = false;
        if (unregister)
            unregister();
        unsubscribePerformance();
        if (pollTimer !== null)
            clearInterval(pollTimer);
        if (inFlight?.timeout != null)
            clearTimeout(inFlight.timeout);
        pendingRequestIds.clear();
    };
}

function replaceMenuItem(items, key, item, before) {
    if (!Array.isArray(items))
        return false;
    const menu = items;
    for (let i = menu.length - 1; i >= 0; i -= 1) {
        if (menu[i]?.key === key)
            menu.splice(i, 1);
    }
    const index = menu.findIndex(before);
    if (index >= 0)
        menu.splice(index, 0, item);
    else
        menu.push(item);
    return true;
}

// Add a "Launch parameters" entry to a game's library context menu (the options
