            replaceMenuItem(menuItems, "pdc-duo-artwork", SP_JSX.jsx(DFL.MenuItem, { onSelected: () => artworkAccess.edit(appid), children: translate("artwork.contextMenu") }, "pdc-duo-artwork"), () => false);
